  (118, $q$The supreme happiness of life consists in the conviction that one is loved; loved for one’s own sake—let us say rather, loved in spite of one’s self.$q$, '[]'::jsonb, $q$Victor Hugo$q$, $q$Les Misérables (trans. Isabel F. Hapgood)$q$, $q$Volume II, Book V? check$q$, $q$https://www.gutenberg.org/ebooks/135$q$, false, 66, 66, null, array[$q$love$q$]::text[], $q$live$q$, 135, null, $q$6f1e61bc8fda9fefcb540f220277937f9e752082a3b7f9689e242eaf7f930667$q$, 400706, 400855, $q$exact$q$, '2026-10-29T01:59:26Z'::timestamptz, $q$5eac8affab7ea3d11dd1c66a4a3b48aaf08a65e5$q$),
  (119, $q$You pierce my soul. I am half agony, half hope. Tell me not that I am too late, that such precious feelings are gone for ever.$q$, '[]'::jsonb, $q$Jane Austen$q$, $q$Persuasion$q$, $q$Chapter XXIII, Captain Wentworth’s letter to Anne$q$, $q$https://www.gutenberg.org/ebooks/105$q$, false, 5, 100, $q$Captain Wentworth$q$, array[$q$love$q$]::text[], $q$live$q$, 105, null, $q$211eca87921e83fa947cbe1b2b1090456cca556e819890380e8173b5b1406ed5$q$, 435337, 435463, $q$exact$q$, '2026-10-29T01:59:26Z'::timestamptz, $q$5eac8affab7ea3d11dd1c66a4a3b48aaf08a65e5$q$),
  (120, $q$All the privilege I claim for my own sex (it is not a very enviable one; you need not covet it), is that of loving longest, when existence or when hope is gone.$q$, '[]'::jsonb, $q$Jane Austen$q$, $q$Persuasion$q$, $q$Chapter XXIII, Anne Elliot to Captain Harville$q$, $q$https://www.gutenberg.org/ebooks/105$q$, false, 5, 100, $q$Anne$q$, array[$q$love$q$]::text[], $q$live$q$, 105, null, $q$211eca87921e83fa947cbe1b2b1090456cca556e819890380e8173b5b1406ed5$q$, 432362, 432523, $q$exact$q$, '2026-10-29T01:59:26Z'::timestamptz, $q$5eac8affab7ea3d11dd1c66a4a3b48aaf08a65e5$q$),
