  (123, $q$We are not enemies, but friends. We must not be enemies. Though passion may have strained, it must not break our bonds of affection.$q$, '[]'::jsonb, $q$Abraham Lincoln$q$, $q$First Inaugural Address$q$, $q$First Inaugural Address, 4 March 1861, closing paragraph$q$, $q$https://www.gutenberg.org/ebooks/14721$q$, false, 36, 103, null, array[$q$love$q$]::text[], $q$live$q$, 14721, null, $q$86b39f464a447eed9d07bd4cb461db40ac66d66571da4cde7de9fc7ec1869b0b$q$, 386044, 386176, $q$exact$q$, '2026-10-29T01:59:26Z'::timestamptz, $q$5eac8affab7ea3d11dd1c66a4a3b48aaf08a65e5$q$),
