insert into public.catalog_authors (id, slug, name, died_year)
  select id, slug, name, died_year from batch_authors on conflict (id) do nothing;
insert into public.catalog_works (id, author_id, citation, edition_year, translator, reporter, contributors_last_died_year, gutenberg_id)
  select id, author_id, citation, edition_year, translator, reporter, contributors_last_died_year, gutenberg_id from batch_works on conflict (id) do nothing;
insert into public.catalog_quotes (id, body, body_format, author, source, source_location, source_url, is_starter, author_id, work_id, speaker, themes, status, checked_ebook_id, checked_wikisource_oldid, checked_body_sha256, checked_start, checked_end, match_kind, checked_at, verifier_version)
  select id, body, body_format, author, source, source_location, source_url, is_starter, author_id, work_id, speaker, themes, status, checked_ebook_id, checked_wikisource_oldid, checked_body_sha256, checked_start, checked_end, match_kind, checked_at, verifier_version from batch_quotes on conflict (id) do nothing;

do $$
begin
  if exists (select 1 from batch_authors b left join public.catalog_authors a on a.id = b.id
             where a.id is null or (a.slug, a.name, a.died_year) is distinct from (b.slug, b.name, b.died_year)) then
    raise exception 'catalog batch 002: an author is already stored with different values';
  end if;
  if exists (select 1 from batch_works b left join public.catalog_works w on w.id = b.id
             where w.id is null or (w.author_id, w.citation, w.edition_year, w.translator, w.reporter, w.contributors_last_died_year, w.gutenberg_id) is distinct from (b.author_id, b.citation, b.edition_year, b.translator, b.reporter, b.contributors_last_died_year, b.gutenberg_id)) then
    raise exception 'catalog batch 002: a work is already stored with different values';
  end if;
  if exists (select 1 from batch_quotes b left join public.catalog_quotes q on q.id = b.id
             where q.id is null or (q.body, q.body_format, q.author, q.source, q.source_location, q.source_url, q.is_starter, q.author_id, q.work_id, q.speaker, q.checked_ebook_id, q.checked_wikisource_oldid, q.checked_body_sha256, q.checked_start, q.checked_end, q.match_kind, q.checked_at, q.verifier_version) is distinct from (b.body, b.body_format, b.author, b.source, b.source_location, b.source_url, b.is_starter, b.author_id, b.work_id, b.speaker, b.checked_ebook_id, b.checked_wikisource_oldid, b.checked_body_sha256, b.checked_start, b.checked_end, b.match_kind, b.checked_at, b.verifier_version)) then
    raise exception 'catalog batch 002: a quote id is already stored with different text or provenance';
  end if;
end
$$;

